import sys
from rich.console import Console
from rich.traceback import Traceback
from io import StringIO

def test_exception_notes():
    console = Console(file=StringIO(), force_terminal=True, record=False)

    try:
        try:
            raise ValueError("Test error")
        except ValueError as e:
            # Python 3.11+ support for __notes__
            if hasattr(e, "__notes__"):
                e.__notes__ = "This is a test note"
            else:
                # For Python < 3.11, we can't really test this via __notes__
                # But since we're likely on 3.11+, this should work.
                # We can manually set it on the object for the purpose of the test 
                # as Traceback.extract uses getattr(exc_value, "__notes__", None)
                e.__notes__ = "This is a test note"
            raise
    except Exception:
        console.print_exception()

    output = console.file.getvalue()
    print(output)
    assert "Notes: This is a test note" in output

if __name__ == "__main__":
    try:
        test_exception_notes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

