import sys
from rich.console import Console
from io import StringIO

def test_exception_notes():
    # Use force_terminal=False to avoid ANSI escape codes in the output
    console = Console(file=StringIO(), force_terminal=False, record=False)

    try:
        try:
            raise ValueError("Test error")
        except ValueError as e:
            e.__notes__ = "This is a test note"
            raise
    except Exception:
        console.print_exception()

    output = console.file.getvalue()
    print(f"Output length: {len(output)}")
    print(f"Output content: {repr(output)}")
    assert "Notes: This is a test note" in output

if __name__ == "__main__":
    try:
        test_exception_notes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)
